update public.techniques
set nombre_en = 'Power rule: bring down the exponent and subtract one',
    descripcion_en = 'To differentiate $c\cdot x^{n}$ multiply the coefficient by the exponent and lower the exponent by one. Lone constants disappear and a sum is differentiated term by term.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Look at each term as $c\\cdot x^{n}$: a number (the coefficient $c$) times x raised to an exponent $n$. Its derivative is $c\\cdot n\\cdot x^{n-1}$.","Two moves, always in this order: the exponent comes down and multiplies the coefficient, and you subtract 1 from the exponent. Example: $(4x^{3})' = 12x^{2}$.","A sum is differentiated term by term, and a lone number (a constant) goes away because its derivative is 0: $(2x^{5} + 3x - 7)' = 10x^{4} + 3$.","Quick check: the exponent of the result is one less than the original. If x appears alone (exponent 1), its derivative is the coefficient: $(3x)' = 3$."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Differentiate $f(x) = 7x^{4}$.","opciones":["$7x^{3}$","$28x^{4}$","$11x^{3}$","$28x^{3}$"],"respuesta":"$28x^{3}$","explicacion":"$7\\cdot 4 = 28$ and the exponent goes down from 4 to 3: $28x^{3}$."},{"pregunta":"Differentiate $f(x) = x^{6} - 5x + 2$.","opciones":["$6x^{5} - 5x$","$6x^{5} - 5$","$x^{5} - 5$","$6x^{5} - 3$"],"respuesta":"$6x^{5} - 5$","explicacion":"Term by term: $6x^{5}$, then $-5$, and the constant 2 disappears."},{"pregunta":"What is the derivative of $f(x) = 8x$?","opciones":["$8x$","$0$","$x$","$8$"],"respuesta":"$8$","explicacion":"x has exponent 1: $8\\cdot 1\\cdot x^{0} = 8$."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":1,"titulo":"Two moves with $4x^3$","cuadros":[{"texto":"The exponent comes down and multiplies","formula":"4\\cdot 3 = 12"},{"texto":"Subtract 1 from the exponent","formula":"(4x^3)' = 12x^2"}]},{"tipo":"calculia.tangente","despuesDePaso":3,"titulo":"$f(x)=x^3$: at $x=1$ the slope is $3\\cdot 1^2 = 3$","funcion":[{"tipo":"potencia","c":1,"n":3}],"x0":1,"rango":[-0.5,1.6]}]$leccion_en$::jsonb
    )
where slug = 'calculia-tec-potencia-baja-exponente';

update public.techniques
set nombre_en = 'Product rule: "differentiate one, keep the other" twice',
    descripcion_en = 'To differentiate $u\cdot v$: differentiate the first and keep the second, then keep the first and differentiate the second, and add: $u''v + uv''$.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["When the function is a product of two factors, $u\\cdot v$, differentiating each one and multiplying isn't enough: $(u\\cdot v)' \\neq u'\\cdot v'$.","The rule: $(u\\cdot v)' = u'\\cdot v + u\\cdot v'$. To remember it: \"differentiate one, keep the other; keep one, differentiate the other; add\".","Example: $f(x) = x^{2}(x^{3}+1)$, with $u = x^{2}$ and $v = x^{3}+1$. Then $f'(x) = 2x(x^{3}+1) + x^{2}\\cdot 3x^{2} = 5x^{4} + 2x$.","Check: here you could multiply first ($x^{5} + x^{2}$) and then differentiate: $(x^{5} + x^{2})' = 5x^{4} + 2x$. Same result; the rule is useful when multiplying first is long or impossible."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Using the product rule, differentiate $f(x) = x^{3}(x^{2}+4)$.","opciones":["$6x^{3}$","$3x^{2}(x^{2}+4)$","$5x^{4} + 4$","$5x^{4} + 12x^{2}$"],"respuesta":"$5x^{4} + 12x^{2}$","explicacion":"$3x^{2}(x^{2}+4) + x^{3}\\cdot 2x = 5x^{4} + 12x^{2}$."},{"pregunta":"What is the product rule?","opciones":["$(uv)' = u'v'$","$(uv)' = u'v - uv'$","$(uv)' = u'v + uv'$","$(uv)' = \\dfrac{u'v - uv'}{v^{2}}$"],"respuesta":"$(uv)' = u'v + uv'$","explicacion":"Each term differentiates one factor and keeps the other; the two terms are added."},{"pregunta":"When differentiating $(2x)(x^{4})$, which is the \"keep the first, differentiate the second\" term?","opciones":["$2x\\cdot 4x^{3}$","$2\\cdot x^{4}$","$2\\cdot 4x^{3}$","$2x\\cdot x^{4}$"],"respuesta":"$2x\\cdot 4x^{3}$","explicacion":"The first one ($2x$) is kept the same and the second one ($x^{4}$) is differentiated: $4x^{3}$."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":2,"titulo":"Product rule with $x^2(x^3+1)$","cuadros":[{"texto":"Differentiate the first, keep the second","formula":"(x^2)'\\cdot(x^3+1) = 2x(x^3+1)"},{"texto":"Keep the first, differentiate the second","formula":"x^2\\cdot(x^3+1)' = 3x^4"},{"texto":"Add","formula":"(x^2(x^3+1))' = 5x^4 + 2x"}]}]$leccion_en$::jsonb
    )
where slug = 'calculia-tec-producto-mnemotecnia';

update public.techniques
set nombre_en = 'Quotient rule: "low times the derivative of high, minus high times the derivative of low"',
    descripcion_en = 'To differentiate $\dfrac{u}{v}$: $\dfrac{u''v - uv''}{v^{2}}$. Always start with the bottom one undifferentiated and don''t forget the square of the denominator.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["The rule: $\\left(\\dfrac{u}{v}\\right)' = \\dfrac{u'\\cdot v - u\\cdot v'}{v^{2}}$. The order matters: there's a subtraction in the numerator, so switching it changes the sign.","A phrase to remember it: \"low times the derivative of high, minus high times the derivative of low, all over low squared\". High is $u$ (numerator) and low is $v$ (denominator).","Example: $f(x) = \\dfrac{x^{2}}{x+1}$, with $u = x^{2}$ and $v = x+1$. You get $f'(x) = \\dfrac{2x(x+1) - x^{2}\\cdot 1}{(x+1)^{2}} = \\dfrac{x^{2}+2x}{(x+1)^{2}}$.","Shortcut: if the denominator is just a number, you don't need the rule: $\\left(\\dfrac{x^{3}}{4}\\right)' = \\dfrac{3x^{2}}{4}$."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Differentiate $f(x) = \\dfrac{2x}{x+3}$ with the quotient rule.","opciones":["$\\dfrac{4x+6}{(x+3)^{2}}$","$2$","$\\dfrac{6}{(x+3)^{2}}$","$\\dfrac{-6}{(x+3)^{2}}$"],"respuesta":"$\\dfrac{6}{(x+3)^{2}}$","explicacion":"$\\dfrac{2(x+3) - 2x\\cdot 1}{(x+3)^{2}} = \\dfrac{6}{(x+3)^{2}}$."},{"pregunta":"In the quotient rule, what goes in the denominator of the result?","opciones":["The derivative of the denominator","The numerator squared","The denominator unchanged","The original denominator squared"],"respuesta":"The original denominator squared","explicacion":"The result is always divided by $v^{2}$."},{"pregunta":"What happens if you switch the order of the subtraction in the numerator?","opciones":["The result changes sign","Nothing changes","It doubles","It becomes zero"],"respuesta":"The result changes sign","explicacion":"$u'v - uv'$ and $uv' - u'v$ are opposites."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":2,"titulo":"Quotient rule with $\\dfrac{x^2}{x+1}$","cuadros":[{"texto":"Low times the derivative of high","formula":"(x+1)\\cdot(x^2)' = 2x(x+1)"},{"texto":"Minus high times the derivative of low","formula":"x^2\\cdot(x+1)' = x^2"},{"texto":"All over low squared","formula":"\\left(\\dfrac{x^2}{x+1}\\right)' = \\dfrac{x^2+2x}{(x+1)^2}"}]}]$leccion_en$::jsonb
    )
where slug = 'calculia-tec-cociente-mnemotecnia';

update public.techniques
set nombre_en = 'Chain rule: from the outside in',
    descripcion_en = 'To differentiate a function inside another, differentiate the outer one leaving the inner one untouched and multiply by the derivative of the inner one.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Recognize it: there's a whole expression tucked inside a power, like $(3x+2)^{4}$. The outer one is \"something to the 4th\" and the inner one is $3x+2$.","Step 1, outside: differentiate as if the inside were a single letter, without touching it: $4(3x+2)^{3}$. Step 2, inside: multiply by the derivative of the inside, which is 3.","Result: $((3x+2)^{4})' = 4(3x+2)^{3}\\cdot 3 = 12(3x+2)^{3}$.","The typical mistake is forgetting step 2. $4(3x+2)^{3}$ would only be correct if the inside had derivative 1, as in $(x+5)^{4}$."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Differentiate $f(x) = (5x-1)^{3}$.","opciones":["$3(5x-1)^{2}$","$15(5x-1)^{3}$","$5(5x-1)^{2}$","$15(5x-1)^{2}$"],"respuesta":"$15(5x-1)^{2}$","explicacion":"Outside: $3(5x-1)^{2}$; inside: 5. Multiplied: $15(5x-1)^{2}$."},{"pregunta":"Differentiate $f(x) = (x^{2}+1)^{5}$.","opciones":["$5(x^{2}+1)^{4}$","$10x(x^{2}+1)^{5}$","$5x(x^{2}+1)^{4}$","$10x(x^{2}+1)^{4}$"],"respuesta":"$10x(x^{2}+1)^{4}$","explicacion":"Outside: $5(x^{2}+1)^{4}$; inside: $2x$. Multiplied: $10x(x^{2}+1)^{4}$."},{"pregunta":"In $(7x+4)^{6}$, which is \"the inner one\"?","opciones":["$u^{6}$","$7$","$7x+4$","$6$"],"respuesta":"$7x+4$","explicacion":"The inner one is the expression inside the parenthesis."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":1,"titulo":"Chain rule with $(3x+2)^4$","cuadros":[{"texto":"Outside: bring down the 4 without touching the inside","formula":"4(3x+2)^3"},{"texto":"Inside: the derivative of $3x+2$","formula":"(3x+2)' = 3"},{"texto":"Multiply","formula":"((3x+2)^4)' = 12(3x+2)^3"}]},{"tipo":"calculia.tangente","despuesDePaso":2,"titulo":"$f(x)=(2x-1)^3$ and its slope at $x=1$","funcion":[{"tipo":"factorLineal","c":1,"a":2,"b":-1,"n":3}],"x0":1,"rango":[0,1.5]}]$leccion_en$::jsonb
    )
where slug = 'calculia-tec-cadena-afuera-adentro';

update public.techniques
set nombre_en = 'Integral of a power: add one to the exponent and divide',
    descripcion_en = 'It''s the power rule in reverse: $\int x^{n}\,dx = \dfrac{x^{n+1}}{n+1} + C$ (for $n \neq -1$). And don''t forget the constant $C$.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Integrating is undoing a derivative: you look for a function whose derivative is the one you're given. For a power, you do the two moves of differentiating backward and in reverse order.","First add 1 to the exponent and then divide by the new exponent: $\\int x^{n}\\,dx = \\dfrac{x^{n+1}}{n+1} + C$.","With a coefficient, the number stays in front and is simplified at the end: $6\\cdot\\dfrac{x^{3}}{3} = 2x^{3}$, so $\\int 6x^{2}\\,dx = 2x^{3} + C$.","Always check by differentiating: $(2x^{3})' = 6x^{2}$, which is what was inside the integral. The $+ C$ is there because any constant has derivative 0."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Compute $\\int 8x^{3}\\,dx$.","opciones":["$8x^{4} + C$","$24x^{2} + C$","$2x^{4} + C$","$2x^{3} + C$"],"respuesta":"$2x^{4} + C$","explicacion":"New exponent 4 and you divide by 4: $\\dfrac{8}{4}x^{4} = 2x^{4}$."},{"pregunta":"Compute $\\int 5\\,dx$.","opciones":["$5x + C$","$5 + C$","$\\dfrac{5x^{2}}{2} + C$","$\\dfrac{5}{x} + C$"],"respuesta":"$5x + C$","explicacion":"$5 = 5x^{0}$: new exponent 1, so it gives $5x$."},{"pregunta":"Why do you add $C$ when integrating?","opciones":["Because it's the constant of the original function","So the result is positive","Because that's how area is written","Because the derivative of any constant is 0"],"respuesta":"Because the derivative of any constant is 0","explicacion":"There are infinitely many antiderivatives that differ only by a constant."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":1,"titulo":"Integrate $3x^2$","cuadros":[{"texto":"Add 1 to the exponent: from 2 to 3"},{"texto":"Divide by the new exponent","formula":"\\int 3x^2\\,dx = x^3 + C"},{"texto":"Check by differentiating","formula":"(x^3)' = 3x^2"}]},{"tipo":"calculia.area","despuesDePaso":3,"titulo":"Area under $3x^2$ between 0 and 2: $2^3 - 0^3 = 8$","funcion":[{"tipo":"potencia","c":3,"n":2}],"desde":0,"hasta":2}]$leccion_en$::jsonb
    )
where slug = 'calculia-tec-integral-potencia';

update public.techniques
set nombre_en = 'The power rule''s exception: k over x gives a logarithm',
    descripcion_en = 'With exponent $-1$ the power rule would divide by 0. That''s why $\int \dfrac{k}{x}\,dx = k\ln|x| + C$: the coefficient stays in front and the natural logarithm appears.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["$\\dfrac{1}{x}$ is $x^{-1}$. If you apply the power rule, the new exponent would be 0 and you'd have to divide by 0: it doesn't work.","The function whose derivative is $\\dfrac{1}{x}$ is the natural logarithm: $(\\ln|x|)' = \\dfrac{1}{x}$. That's why $\\int \\dfrac{1}{x}\\,dx = \\ln|x| + C$.","With a number on top, that number comes out in front: $\\int \\dfrac{6}{x}\\,dx = 6\\ln|x| + C$.","The absolute value bars are there because the logarithm only exists for positive numbers; that way the formula also works for negative x."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Compute $\\int \\dfrac{5}{x}\\,dx$.","opciones":["$\\dfrac{5}{x^{2}} + C$","$5\\ln|x| + C$","$5x + C$","$\\ln|5x| + C$"],"respuesta":"$5\\ln|x| + C$","explicacion":"The 5 comes out in front and $\\int \\dfrac{1}{x}\\,dx = \\ln|x|$."},{"pregunta":"Why doesn't the power rule work for $\\dfrac{1}{x}$?","opciones":["Because x has no exponent","Because you'd have to divide by 0","Because the integral doesn't exist","Because it gives a negative number"],"respuesta":"Because you'd have to divide by 0","explicacion":"With $n = -1$ the new exponent is 0 and the formula divides by $n+1 = 0$."},{"pregunta":"What is the derivative of $\\ln|x|$?","opciones":["$\\ln|x|$","$x$","$e^{x}$","$\\dfrac{1}{x}$"],"respuesta":"$\\dfrac{1}{x}$","explicacion":"$(\\ln|x|)' = \\dfrac{1}{x}$: that's why the integral of $\\dfrac{1}{x}$ is the logarithm."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":1,"titulo":"Why the logarithm shows up","cuadros":[{"texto":"Write the fraction as a power","formula":"\\dfrac{1}{x} = x^{-1}"},{"texto":"The power rule would ask you to divide by 0; the logarithm solves that case","formula":"(\\ln|x|)' = \\dfrac{1}{x}"},{"texto":"With a coefficient","formula":"\\int \\dfrac{3}{x}\\,dx = 3\\ln|x| + C"}]}]$leccion_en$::jsonb
    )
where slug = 'calculia-tec-integral-uno-sobre-x';

update public.techniques
set nombre_en = 'Exponential: e to the ax is integrated by dividing by a',
    descripcion_en = '$e^{x}$ is its own derivative and its own integral. With $e^{ax}$, differentiating brings out a factor $a$; integrating means dividing by $a$.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["The function $e^{x}$ has a unique property: its derivative is itself, $(e^{x})' = e^{x}$. That's why $\\int e^{x}\\,dx = e^{x} + C$ too.","If the exponent is a number times x, the chain rule brings that number out when differentiating: $(e^{3x})' = 3e^{3x}$.","When integrating you do the opposite, you divide by that number: $\\int e^{3x}\\,dx = \\dfrac{e^{3x}}{3} + C$.","Check by differentiating: $\\left(\\dfrac{e^{3x}}{3}\\right)' = \\dfrac{3e^{3x}}{3} = e^{3x}$."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Compute $\\int e^{4x}\\,dx$.","opciones":["$4e^{4x} + C$","$\\dfrac{e^{4x}}{4} + C$","$e^{4x} + C$","$\\dfrac{e^{5x}}{5} + C$"],"respuesta":"$\\dfrac{e^{4x}}{4} + C$","explicacion":"You divide by the 4 in the exponent."},{"pregunta":"Compute $\\int 10e^{5x}\\,dx$.","opciones":["$50e^{5x} + C$","$10e^{5x} + C$","$5e^{5x} + C$","$2e^{5x} + C$"],"respuesta":"$2e^{5x} + C$","explicacion":"$\\dfrac{10}{5}e^{5x} = 2e^{5x}$; differentiating gives $10e^{5x}$ back."},{"pregunta":"What is the derivative of $e^{x}$?","opciones":["$xe^{x-1}$","$e$","$0$","$e^{x}$"],"respuesta":"$e^{x}$","explicacion":"The exponential is its own derivative (the power rule doesn't apply to it)."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":2,"titulo":"Differentiating multiplies, integrating divides","cuadros":[{"texto":"Differentiating brings out a factor of 2","formula":"(e^{2x})' = 2e^{2x}"},{"texto":"Integrating divides by 2","formula":"\\int e^{2x}\\,dx = \\dfrac{e^{2x}}{2} + C"},{"texto":"With a coefficient","formula":"\\int 6e^{2x}\\,dx = 3e^{2x} + C"}]}]$leccion_en$::jsonb
    )
where slug = 'calculia-tec-integral-exponencial';

update public.techniques
set nombre_en = 'Sine and cosine: the minus sign goes with the cosine',
    descripcion_en = '$\int \cos(x)\,dx = \sin(x) + C$ and $\int \sin(x)\,dx = -\cos(x) + C$. Trick: when integrating, the minus appears when the result is a cosine.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Remember the derivatives: $(\\sin(x))' = \\cos(x)$ and $(\\cos(x))' = -\\sin(x)$.","Integrating undoes them: $\\int \\cos(x)\\,dx = \\sin(x) + C$ and $\\int \\sin(x)\\,dx = -\\cos(x) + C$.","So you don't mix up the sign: when integrating the sine, the minus ends up in front of the cosine. Check it by differentiating: $(-\\cos(x))' = \\sin(x)$.","Coefficients come out in front: $\\int 4\\cos(x)\\,dx = 4\\sin(x) + C$ and $\\int 3\\sin(x)\\,dx = -3\\cos(x) + C$."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Compute $\\int 6\\cos(x)\\,dx$.","opciones":["$-6\\sin(x) + C$","$6\\cos(x) + C$","$6\\sin(x) + C$","$-6\\cos(x) + C$"],"respuesta":"$6\\sin(x) + C$","explicacion":"Integrating cosine gives sine, with no minus sign."},{"pregunta":"Compute $\\int 2\\sin(x)\\,dx$.","opciones":["$2\\cos(x) + C$","$-2\\sin(x) + C$","$2\\sin(x) + C$","$-2\\cos(x) + C$"],"respuesta":"$-2\\cos(x) + C$","explicacion":"Integrating sine gives minus cosine: $(-2\\cos(x))' = 2\\sin(x)$."},{"pregunta":"What is the derivative of $\\cos(x)$?","opciones":["$\\sin(x)$","$-\\cos(x)$","$-\\sin(x)$","$\\cos(x)$"],"respuesta":"$-\\sin(x)$","explicacion":"Differentiating cosine gives minus sine."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":2,"titulo":"The sine and cosine cycle","cuadros":[{"texto":"Differentiating sine gives cosine","formula":"(\\operatorname{sen}(x))' = \\cos(x)"},{"texto":"Differentiating cosine gives minus sine","formula":"(\\cos(x))' = -\\operatorname{sen}(x)"},{"texto":"When integrating the sine, the minus stays with the cosine","formula":"\\int 2\\operatorname{sen}(x)\\,dx = -2\\cos(x) + C"}]}]$leccion_en$::jsonb
    )
where slug = 'calculia-tec-integral-seno-coseno';

update public.techniques
set nombre_en = 'Substitution: look for something whose derivative is already outside',
    descripcion_en = 'If inside the integral there''s an expression raised to a power and outside there''s (up to a number) its derivative, call it $u$ and the integral becomes a simple power.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["The signal: a parenthesis raised to something, like $(2x+3)^{4}$, and outside a number related to the derivative of the inside (here, $(2x+3)' = 2$).","Call the inside $u$: $u = 2x+3$. Since $du = 2\\,dx$, each $dx$ is replaced by $\\dfrac{du}{2}$.","Example: in $\\int 10(2x+3)^{4}\\,dx$, with $u = 2x+3$ you get $\\int 5u^{4}\\,du$, which gives $u^{5} + C$. Going back to x: $(2x+3)^{5} + C$.","Check with the chain rule: $((2x+3)^{5})' = 5(2x+3)^{4}\\cdot 2 = 10(2x+3)^{4}$. So $\\int 10(2x+3)^{4}\\,dx = (2x+3)^{5} + C$."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Compute $\\int 12(3x+1)^{3}\\,dx$ with $u = 3x+1$.","opciones":["$3(3x+1)^{4} + C$","$12(3x+1)^{4} + C$","$(3x+1)^{4} + C$","$(3x+1)^{3} + C$"],"respuesta":"$(3x+1)^{4} + C$","explicacion":"$du = 3\\,dx$: you get $\\int 4u^{3}\\,du = u^{4} + C$."},{"pregunta":"In $\\int 8(4x-5)^{2}\\,dx$, what's best to call $u$?","opciones":["$8$","$(4x-5)^{2}$","$x$","$4x-5$"],"respuesta":"$4x-5$","explicacion":"$u$ is what's inside the parenthesis; its derivative (4) divides the 8."},{"pregunta":"If $u = 2x+3$, what is $dx$ replaced by?","opciones":["$2\\,du$","$du$","$\\dfrac{du}{2}$","$3\\,du$"],"respuesta":"$\\dfrac{du}{2}$","explicacion":"$du = 2\\,dx$, so $dx = \\dfrac{du}{2}$."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":1,"titulo":"Substitution in $\\int 10(2x+3)^4\\,dx$","cuadros":[{"texto":"The inside is $u$","formula":"u = 2x+3"},{"texto":"Its derivative is already outside (10 is 5 times 2)","formula":"(2x+3)' = 2"},{"texto":"Integrate the power and go back to x","formula":"\\int 10(2x+3)^4\\,dx = (2x+3)^5 + C"}]}]$leccion_en$::jsonb
    )
where slug = 'calculia-tec-sustitucion-reconocer';

update public.techniques
set nombre_en = 'Geometric series: it converges only if the ratio is between −1 and 1',
    descripcion_en = 'In $a + ar + ar^{2} + \dots$ each term is the previous one times $r$. If $|r| < 1$ the terms shrink and the series converges; if $|r| \geq 1$, it diverges.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["A geometric series adds terms that are always multiplied by the same number, the ratio $r$. For example, $3 + \\dfrac{3}{2} + \\dfrac{3}{4} + \\dots$ has ratio one half.","To find $r$, divide a term by the previous one: $\\dfrac{3/4}{3/2} = \\dfrac{1}{2}$.","Rule: if $|r| < 1$ (for example, two thirds or minus one quarter), the series converges. If $|r| \\geq 1$ (like 2 or minus three halves), it diverges.","The sign doesn't decide: look at the absolute value. With ratio minus four fifths the terms switch sign but shrink, so it converges."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Does the geometric series with ratio $r = -\\dfrac{2}{3}$ converge or diverge?","opciones":["It converges","It diverges"],"respuesta":"It converges","explicacion":"$|r| = \\dfrac{2}{3} < 1$: it converges."},{"pregunta":"Does the geometric series with ratio $r = \\dfrac{5}{4}$ converge or diverge?","opciones":["It diverges","It converges"],"respuesta":"It diverges","explicacion":"$|r| = \\dfrac{5}{4} \\geq 1$: it diverges."},{"pregunta":"What is the ratio of $2 + 6 + 18 + 54 + \\dots$?","opciones":["2","3","4","$\\dfrac{1}{3}$"],"respuesta":"3","explicacion":"Each term is the previous one times 3: $\\dfrac{6}{2} = 3$."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"calculia.serie","despuesDePaso":0,"titulo":"Ratio $\\frac{1}{2}$: the partial sums approach 6","a":3,"rNum":1,"rDen":2,"terminos":8},{"tipo":"calculia.serie","despuesDePaso":2,"titulo":"Ratio $\\frac{3}{2}$: the sums grow without limit","a":1,"rNum":3,"rDen":2,"terminos":6}]$leccion_en$::jsonb
    )
where slug = 'calculia-tec-geometrica-converge';

update public.techniques
set nombre_en = 'Infinite sum of a geometric series: first term over one minus the ratio',
    descripcion_en = 'If $|r| < 1$, the infinite sum is $\dfrac{a}{1-r}$, with $a$ the first term. Watch the signs when the ratio is negative.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["You can only add \"up to infinity\" if the series converges, that is, if $|r| < 1$. If not, the sum doesn't exist.","The sum formula is $\\dfrac{a}{1-r}$, where $a$ is the first term and $r$ the ratio.","Example: first term 4 and ratio one half: $\\dfrac{4}{1-\\frac{1}{2}} = \\dfrac{4}{\\frac{1}{2}} = 8$.","With a negative ratio, the minus becomes a plus: first term 6 and ratio minus one half give $\\dfrac{6}{1+\\frac{1}{2}} = 4$."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Compute the infinite sum with first term 9 and ratio $\\dfrac{2}{3}$.","opciones":["27","18","13.5","6"],"respuesta":"27","explicacion":"$\\dfrac{9}{1-\\frac{2}{3}} = \\dfrac{9}{\\frac{1}{3}} = 27$."},{"pregunta":"Compute the infinite sum with first term 10 and ratio $-\\dfrac{1}{4}$.","opciones":["8","13.33","40","7.5"],"respuesta":"8","explicacion":"$\\dfrac{10}{1+\\frac{1}{4}} = \\dfrac{10}{\\frac{5}{4}} = 8$."},{"pregunta":"When does the infinite sum of a geometric series exist?","opciones":["Always","When $|r| < 1$","When $r > 1$","When $a < 1$"],"respuesta":"When $|r| < 1$","explicacion":"Only if the terms shrink enough: $|r| < 1$."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"calculia.serie","despuesDePaso":2,"titulo":"$\\dfrac{4}{1-\\frac{1}{2}} = 8$","a":4,"rNum":1,"rDen":2,"terminos":8}]$leccion_en$::jsonb
    )
where slug = 'calculia-tec-suma-geometrica';

update public.techniques
set nombre_en = 'p-series: it converges if the exponent is greater than 1',
    descripcion_en = '$\sum \dfrac{1}{n^{p}}$ converges if $p > 1$ and diverges if $p \leq 1$. The borderline case $p = 1$ is the harmonic series, which diverges.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["A p-series adds the reciprocals of the powers of the natural numbers: $\\sum_{n=1}^{\\infty} \\dfrac{1}{n^{p}}$, that is, $1 + \\dfrac{1}{2^{p}} + \\dfrac{1}{3^{p}} + \\dots$","One rule: if $p > 1$ it converges; if $p \\leq 1$ it diverges. With $p = 2$ it converges; with $p = 0{,}5$ (a square root in the denominator) it diverges.","Watch out for $p = 1$: it's the harmonic series, $1 + \\dfrac{1}{2} + \\dfrac{1}{3} + \\dots$ Its terms shrink, but the sum grows without limit. It's not enough for the terms to go to 0.","Don't confuse it with the geometric one: in the p-series the $n$ is in the base ($n^{p}$); in the geometric one, in the exponent ($r^{n}$)."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Does the series $\\sum \\dfrac{1}{n^{3}}$ converge or diverge?","opciones":["It converges","It diverges"],"respuesta":"It converges","explicacion":"It's a p-series with $p = 3 > 1$."},{"pregunta":"Does the harmonic series $\\sum \\dfrac{1}{n}$ converge or diverge?","opciones":["It diverges","It converges"],"respuesta":"It diverges","explicacion":"It's the p-series with $p = 1$: it diverges even though its terms go to 0."},{"pregunta":"For which values of $p$ does the p-series converge?","opciones":["$p \\geq 1$","$p < 1$","$p > 1$","$p > 0$"],"respuesta":"$p > 1$","explicacion":"It converges exactly when $p > 1$."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":1,"titulo":"Three p-series","cuadros":[{"texto":"$p = 2$: converges","formula":"1 + \\dfrac{1}{4} + \\dfrac{1}{9} + \\dfrac{1}{16} + \\dots","resaltar":"Con 10 términos suma $1{,}55$"},{"texto":"$p = 1$: the harmonic series diverges","formula":"1 + \\dfrac{1}{2} + \\dfrac{1}{3} + \\dfrac{1}{4} + \\dots","resaltar":"Con 1000 términos ya pasa de 7"},{"texto":"$p = 0{,}5$: diverges","formula":"1 + \\dfrac{1}{\\sqrt{2}} + \\dfrac{1}{\\sqrt{3}} + \\dots"}]}]$leccion_en$::jsonb
    )
where slug = 'calculia-tec-serie-p';

update public.techniques
set nombre_en = 'Ratio test: divide a term by the previous one',
    descripcion_en = 'Compute the limit of $\left|\dfrac{a_{n+1}}{a_{n}}\right|$. If it''s less than 1 the series converges, if it''s greater than 1 it diverges and if it''s 1 the test doesn''t decide.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["The ratio test compares each term with the previous one. Compute $L = \\lim_{n\\to\\infty}\\left|\\dfrac{a_{n+1}}{a_{n}}\\right|$.","Decide: if $L < 1$ the series converges; if $L > 1$ it diverges; if L is exactly 1, the test doesn't work and you have to use another one.","For $a_{n} = c\\cdot r^{n}$, the quotient between a term and the previous one is always $r$ (the $c$ cancels out), so L is the absolute value of $r$.","Example: with $a_{n} = 5\\cdot\\left(\\dfrac{2}{3}\\right)^{n}$, L is two thirds, less than 1: it converges. With $a_{n} = 2\\cdot\\left(-\\dfrac{3}{2}\\right)^{n}$, L is three halves: it diverges."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"For $a_{n} = 4\\cdot\\left(\\dfrac{3}{5}\\right)^{n}$, what is L in the ratio test?","opciones":["4","$\\dfrac{12}{5}$","$\\dfrac{3}{5}$","$\\dfrac{5}{3}$"],"respuesta":"$\\dfrac{3}{5}$","explicacion":"The $c = 4$ cancels out and L is the absolute value of the ratio: $\\dfrac{3}{5}$."},{"pregunta":"If the ratio test gives $L = 2$, the series...","opciones":["Converges","The test doesn't decide","Diverges"],"respuesta":"Diverges","explicacion":"$L > 1$: it diverges."},{"pregunta":"If the ratio test gives $L = 1$, what do you conclude?","opciones":["That it converges","Nothing: you have to use another test","That it diverges"],"respuesta":"Nothing: you have to use another test","explicacion":"With $L = 1$ some series converge and others diverge."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":2,"titulo":"Ratio test with $a_n = 5\\cdot\\left(\\frac{2}{3}\\right)^n$","cuadros":[{"texto":"Next term over the current one","formula":"\\dfrac{a_{n+1}}{a_{n}}"},{"texto":"The $c$ cancels out and the ratio is left","formula":"\\dfrac{5\\cdot(2/3)^{4}}{5\\cdot(2/3)^{3}} = \\dfrac{2}{3}"},{"texto":"It's less than 1","resaltar":"La serie converge"}]}]$leccion_en$::jsonb
    )
where slug = 'calculia-tec-criterio-razon';

update public.techniques
set nombre_en = 'Partials term by term: the other variable travels along like a number',
    descripcion_en = 'To differentiate with respect to x, each term is differentiated with the power rule in x and the power of y stays the same, multiplying. Terms without x disappear.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Go through the polynomial term by term. In each one, separate the part with x from the part with y.","For $\\dfrac{\\partial f}{\\partial x}$: apply the power rule only to the x and leave the power of y as it is. So $4x^{3}y^{2}$ gives $12x^{2}y^{2}$.","A term without x (like $7y^{3}$) is a constant for $\\dfrac{\\partial f}{\\partial x}$: its partial is 0. And one without y (like $5x^{2}$) disappears in $\\dfrac{\\partial f}{\\partial y}$.","Full example: for $f(x,y) = 4x^{3}y^{2} + 5x^{2} + 7y^{3}$, the partial with respect to x is $12x^{2}y^{2} + 10x$ and the partial with respect to y is $8x^{3}y + 21y^{2}$."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"For $f(x,y) = 3x^{2}y^{4} + 2y$, compute $\\dfrac{\\partial f}{\\partial x}$.","opciones":["$6xy^{4} + 2$","$6xy^{4}$","$24xy^{3}$","$6x$"],"respuesta":"$6xy^{4}$","explicacion":"$3x^{2}y^{4}$ gives $6xy^{4}$ and $2y$ has no x: it gives 0."},{"pregunta":"For $f(x,y) = 3x^{2}y^{4} + 2y$, compute $\\dfrac{\\partial f}{\\partial y}$.","opciones":["$12x^{2}y^{3}$","$12x^{2}y^{3} + 2$","$12xy^{3} + 2$","$6xy^{4} + 2$"],"respuesta":"$12x^{2}y^{3} + 2$","explicacion":"$3x^{2}y^{4}$ gives $12x^{2}y^{3}$ and $2y$ gives 2."},{"pregunta":"When computing $\\dfrac{\\partial f}{\\partial x}$, what happens to a term that only has y?","opciones":["Its partial is 0","It stays the same","It's differentiated with respect to y","It's multiplied by x"],"respuesta":"Its partial is 0","explicacion":"For the partial in x, y is a constant, and the derivative of a constant is 0."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":1,"titulo":"With respect to x in $4x^3y^2 + 5x^2 + 7y^3$","cuadros":[{"texto":"$4x^3y^2$: differentiate the x, keep $y^2$","formula":"12x^2y^2"},{"texto":"$5x^2$","formula":"10x"},{"texto":"$7y^3$ has no x","formula":"0"}]}]$leccion_en$::jsonb
    )
where slug = 'calculia-tec-parcial-terminos-mixtos';

update public.techniques
set nombre_en = 'If the derivative is proportional to the function, the solution is exponential',
    descripcion_en = 'The equation $\dfrac{dy}{dx} = k\cdot y$ (it changes in proportion to what''s there) always has the solution $y = A\cdot e^{kx}$.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Many things change in proportion to their size: a population, money with compound interest, a substance that decays. That's written $\\dfrac{dy}{dx} = k\\cdot y$.","The solution is always $y = A\\cdot e^{kx}$, where $A$ is the value at $x = 0$. If $k > 0$ it grows; if $k < 0$ it decreases.","Check it: differentiating $A\\cdot e^{kx}$ gives $k\\cdot A\\cdot e^{kx}$, which is $k$ times the same function.","Example: $\\dfrac{dy}{dx} = 3y$ has the solution $y = A\\cdot e^{3x}$. Check: $(e^{3x})' = 3e^{3x}$."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"What is the general solution of $\\dfrac{dy}{dx} = 5y$?","opciones":["$y = A\\cdot e^{x/5}$","$y = 5x + A$","$y = A\\cdot x^{5}$","$y = A\\cdot e^{5x}$"],"respuesta":"$y = A\\cdot e^{5x}$","explicacion":"If the derivative is 5 times the function, the solution is $A\\cdot e^{5x}$."},{"pregunta":"If $k < 0$ in $\\dfrac{dy}{dx} = k\\cdot y$, the quantity...","opciones":["Grows","Stays the same","Decreases"],"respuesta":"Decreases","explicacion":"With $k < 0$, $e^{kx}$ shrinks as x grows."},{"pregunta":"In $y = A\\cdot e^{kx}$, what does $A$ represent?","opciones":["The growth speed","The derivative of y","The value of y when $x = 0$","A number that's always 1"],"respuesta":"The value of y when $x = 0$","explicacion":"At $x = 0$, $e^{0} = 1$ and you're left with $y = A$."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"calculia.edo","despuesDePaso":1,"titulo":"Solutions of $\\dfrac{dy}{dx} = 2y$","k":2,"n":0,"x0":0.5,"rango":[-1.2,1.2]}]$leccion_en$::jsonb
    )
where slug = 'calculia-tec-edo-exponencial';

update public.techniques
set nombre_en = 'Product rule: differentiating a multiplication of functions',
    descripcion_en = 'Why the derivative of a product isn''t the product of the derivatives, where $u''v + uv''$ comes from, worked examples and how to check them.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["When $f(x)$ is a product of two functions, $u\\cdot v$, the temptation is to differentiate each one and multiply. That's wrong: with $u = x$ and $v = x$ the product is $x^{2}$, whose derivative is $2x$, but the product of the derivatives is $1\\cdot 1 = 1$.","The correct rule: $(u\\cdot v)' = u'\\cdot v + u\\cdot v'$. Each term differentiates one factor and leaves the other intact. With $u = v = x$: $1\\cdot x + x\\cdot 1 = 2x$.","Idea of why it works: if $u$ and $v$ are the sides of a rectangle, its area is $u\\cdot v$. When both grow a little, the area gains a strip along each side, one of size $u'\\cdot v$ and another of $u\\cdot v'$; the little leftover corner is negligible.","Worked example: $f(x) = 3x^{2}(x^{4} - 2)$, with $u = 3x^{2}$ and $v = x^{4} - 2$. Then $f'(x) = 6x(x^{4} - 2) + 3x^{2}\\cdot 4x^{3} = 18x^{5} - 12x$.","Check: multiplying first, $(3x^{6} - 6x^{2})' = 18x^{5} - 12x$. It matches. The rule is essential when you can't multiply first, as in $x^{2}e^{x}$: $(x^{2}e^{x})' = 2xe^{x} + x^{2}e^{x}$.","Common mistakes: multiplying the derivatives; forgetting one of the two terms; and getting the sign wrong when a factor has a subtraction. With three factors the rule extends: differentiate one at a time and add the three terms."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Differentiate $f(x) = x^{2}(x^{3} + 5)$.","opciones":["$6x^{3}$","$5x^{4} + 5$","$2x(x^{3}+5)$","$5x^{4} + 10x$"],"respuesta":"$5x^{4} + 10x$","explicacion":"$2x(x^{3}+5) + x^{2}\\cdot 3x^{2} = 5x^{4} + 10x$."},{"pregunta":"Differentiate $f(x) = x\\cdot e^{x}$.","opciones":["$e^{x}$","$xe^{x}$","$xe^{x-1}$","$e^{x} + xe^{x}$"],"respuesta":"$e^{x} + xe^{x}$","explicacion":"$u = x$, $v = e^{x}$: $1\\cdot e^{x} + x\\cdot e^{x}$."},{"pregunta":"What is the product rule?","opciones":["$(uv)' = u'v'$","$(uv)' = u'v - uv'$","$(uv)' = u'v + uv'$","$(uv)' = \\dfrac{u'}{v'}$"],"respuesta":"$(uv)' = u'v + uv'$","explicacion":"Differentiate one and keep the other, twice, and add."},{"pregunta":"With $u = 2x$ and $v = x^{3}$, what is $u'\\cdot v$?","opciones":["$2x^{3}$","$6x^{3}$","$6x^{2}$","$2$"],"respuesta":"$2x^{3}$","explicacion":"$u' = 2$, so $u'\\cdot v = 2x^{3}$."},{"pregunta":"What is the most common mistake with the product rule?","opciones":["Adding the functions","Dividing by $v^{2}$","Multiplying the two derivatives","Subtracting 1 from the exponent"],"respuesta":"Multiplying the two derivatives","explicacion":"$(uv)'$ isn't $u'v'$: the cross terms are missing."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":3,"titulo":"Product rule with $3x^2(x^4-2)$","cuadros":[{"texto":"Differentiate the first, keep the second","formula":"(3x^2)'\\cdot(x^4-2) = 6x(x^4-2)"},{"texto":"Keep the first, differentiate the second","formula":"3x^2\\cdot(x^4-2)' = 12x^5"},{"texto":"Add and simplify","formula":"6x(x^4-2) + 12x^5 = 18x^5 - 12x"}]},{"tipo":"calculia.tangente","despuesDePaso":4,"titulo":"$f(x)=3x^6-6x^2$: at $x=1$ the slope is $18 - 12 = 6$","funcion":[{"tipo":"potencia","c":3,"n":6},{"tipo":"potencia","c":-6,"n":2}],"x0":1,"rango":[0,1.25]}]$leccion_en$::jsonb
    )
where slug = 'calculia-clase-regla-producto';

update public.techniques
set nombre_en = 'Quotient rule: differentiating a division',
    descripcion_en = 'The formula $\dfrac{u''v - uv''}{v^{2}}$, why the order matters, worked examples and when it''s better to avoid it.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["If $f(x) = \\dfrac{u}{v}$, its derivative is $f'(x) = \\dfrac{u'\\cdot v - u\\cdot v'}{v^{2}}$, as long as $v$ isn't 0.","Unlike the product, here there's a subtraction: if you flip the order of the numerator, the result changes sign. A phrase to remember it: \"low times the derivative of high, minus high times the derivative of low, over low squared\".","Worked example: $f(x) = \\dfrac{3x+1}{x-2}$, with $u' = 3$ and $v' = 1$. Then $f'(x) = \\dfrac{3(x-2) - (3x+1)\\cdot 1}{(x-2)^{2}} = \\dfrac{-7}{(x-2)^{2}}$.","Another example: for $\\dfrac{x^{2}}{x^{2}+1}$ the derivative is $\\dfrac{2x(x^{2}+1) - x^{2}\\cdot 2x}{(x^{2}+1)^{2}} = \\dfrac{2x}{(x^{2}+1)^{2}}$.","When to avoid it: if the denominator is a number, divide and use the power rule: $\\left(\\dfrac{x^{4}}{2}\\right)' = 2x^{3}$. If it's a power of x, rewrite with a negative exponent: $\\dfrac{5}{x^{2}} = 5x^{-2}$, whose derivative is $-10x^{-3}$.","Common mistakes: flipping the subtraction in the numerator (it changes the sign of everything); forgetting to square the denominator; and simplifying the numerator badly: expand and reduce before giving the result."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Differentiate $f(x) = \\dfrac{x}{x+1}$.","opciones":["$\\dfrac{1}{(x+1)^{2}}$","$\\dfrac{-1}{(x+1)^{2}}$","$\\dfrac{2x+1}{(x+1)^{2}}$","$1$"],"respuesta":"$\\dfrac{1}{(x+1)^{2}}$","explicacion":"$\\dfrac{1\\cdot(x+1) - x\\cdot 1}{(x+1)^{2}} = \\dfrac{1}{(x+1)^{2}}$."},{"pregunta":"Differentiate $f(x) = \\dfrac{2x^{2}}{x+3}$.","opciones":["$\\dfrac{6x^{2}+12x}{(x+3)^{2}}$","$\\dfrac{2x^{2}+12x}{(x+3)^{2}}$","$4x$","$\\dfrac{-2x^{2}-12x}{(x+3)^{2}}$"],"respuesta":"$\\dfrac{2x^{2}+12x}{(x+3)^{2}}$","explicacion":"$\\dfrac{4x(x+3) - 2x^{2}}{(x+3)^{2}} = \\dfrac{2x^{2}+12x}{(x+3)^{2}}$."},{"pregunta":"What changes if you flip the order of the subtraction in the numerator?","opciones":["Nothing","The denominator","The exponent","The sign of the result"],"respuesta":"The sign of the result","explicacion":"$u'v - uv'$ and $uv' - u'v$ are opposites."},{"pregunta":"What is the derivative of $\\dfrac{3}{x}$?","opciones":["$\\dfrac{3}{x^{2}}$","$3\\ln|x|$","$0$","$-\\dfrac{3}{x^{2}}$"],"respuesta":"$-\\dfrac{3}{x^{2}}$","explicacion":"$\\dfrac{3}{x} = 3x^{-1}$, whose derivative is $-3x^{-2}$."},{"pregunta":"In $\\dfrac{u'v - uv'}{v^{2}}$, what is $v$?","opciones":["The numerator","The derivative of the numerator","The result","The denominator"],"respuesta":"The denominator","explicacion":"$u$ is the top and $v$ the bottom."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":2,"titulo":"Quotient rule with $\\dfrac{3x+1}{x-2}$","cuadros":[{"texto":"Low times the derivative of high","formula":"(x-2)\\cdot(3x+1)' = 3(x-2)"},{"texto":"Minus high times the derivative of low","formula":"(3x+1)\\cdot(x-2)' = 3x+1"},{"texto":"Over low squared","formula":"\\left(\\dfrac{3x+1}{x-2}\\right)' = \\dfrac{-7}{(x-2)^2}"}]}]$leccion_en$::jsonb
    )
where slug = 'calculia-clase-regla-cociente';

update public.techniques
set nombre_en = 'Chain rule: functions inside functions',
    descripcion_en = 'How to recognize a composition, differentiate from the outside in and apply it to powers of binomials, exponentials and trigonometric functions.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["A composition is a function inside another: in $(2x+5)^{3}$ the outer one is \"cubing\" and the inner one is $2x+5$. In $e^{4x}$, the outer one is the exponential and the inner one, $4x$.","The rule: differentiate the outer one leaving the inner one the same, and multiply by the derivative of the inner one. In symbols, the derivative of $g(u(x))$ is $g'(u)\\cdot u'(x)$.","Powers of a binomial: $((2x+5)^{3})' = 3(2x+5)^{2}\\cdot 2 = 6(2x+5)^{2}$.","Exponentials and trigonometric functions follow the same idea: $(e^{4x})' = 4e^{4x}$ and $(\\sin(3x))' = 3\\cos(3x)$.","With something more complex inside: $((x^{2}+1)^{4})' = 4(x^{2}+1)^{3}\\cdot 2x = 8x(x^{2}+1)^{3}$.","Common mistakes: forgetting to multiply by the derivative of the inside (it's mistake number one); also differentiating the inside in the first step (it's left intact); and confusing composition with product: $x^{2}\\cdot e^{x}$ is a product, $e^{x^{2}}$ is a composition."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Differentiate $f(x) = (4x-3)^{5}$.","opciones":["$5(4x-3)^{4}$","$20(4x-3)^{5}$","$4(4x-3)^{4}$","$20(4x-3)^{4}$"],"respuesta":"$20(4x-3)^{4}$","explicacion":"Outside $5(4x-3)^{4}$, inside 4: $20(4x-3)^{4}$."},{"pregunta":"Differentiate $f(x) = e^{6x}$.","opciones":["$e^{6x}$","$6xe^{6x}$","$6e^{6x}$","$\\dfrac{e^{6x}}{6}$"],"respuesta":"$6e^{6x}$","explicacion":"The exponential stays the same and is multiplied by the derivative of $6x$."},{"pregunta":"Differentiate $f(x) = \\cos(2x)$.","opciones":["$-\\sin(2x)$","$2\\sin(2x)$","$-2\\cos(2x)$","$-2\\sin(2x)$"],"respuesta":"$-2\\sin(2x)$","explicacion":"Outside: $-\\sin(2x)$; inside: 2."},{"pregunta":"Differentiate $f(x) = (x^{3}+2)^{2}$.","opciones":["$2(x^{3}+2)$","$3x^{2}(x^{3}+2)$","$6x^{2}(x^{3}+2)$","$6x^{2}(x^{3}+2)^{2}$"],"respuesta":"$6x^{2}(x^{3}+2)$","explicacion":"$2(x^{3}+2)\\cdot 3x^{2} = 6x^{2}(x^{3}+2)$."},{"pregunta":"Which of these functions is a composition?","opciones":["$e^{x^{2}}$","$x^{2}\\cdot e^{x}$","$x^{2} + e^{x}$","$3x^{2}$"],"respuesta":"$e^{x^{2}}$","explicacion":"In $e^{x^{2}}$ the function $x^{2}$ is inside the exponential."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":2,"titulo":"Chain rule with $(2x+5)^3$","cuadros":[{"texto":"Outside: the cube, without touching the inside","formula":"3(2x+5)^2"},{"texto":"Inside: the derivative of $2x+5$","formula":"(2x+5)' = 2"},{"texto":"Multiply","formula":"((2x+5)^3)' = 6(2x+5)^2"}]},{"tipo":"calculia.tangente","despuesDePaso":2,"titulo":"$f(x)=(2x+5)^3$: at $x=-2$ the slope is $6\\cdot 1^2 = 6$","funcion":[{"tipo":"factorLineal","c":1,"a":2,"b":5,"n":3}],"x0":-2,"rango":[-3,-1.5]}]$leccion_en$::jsonb
    )
where slug = 'calculia-clase-regla-cadena';

update public.techniques
set nombre_en = 'The definite integral: area under the curve and the fundamental theorem',
    descripcion_en = 'What $\int_{a}^{b} f(x)\,dx$ measures, how it''s computed with an antiderivative, and what happens when the curve is below the axis.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["The definite integral $\\int_{a}^{b} f(x)\\,dx$ adds up the area between the curve of $f$ and the x axis, from a to b. It can be approximated with thinner and thinner rectangles (Riemann sums).","The fundamental theorem of calculus gives the exact value: if $F$ is an antiderivative of $f$, the definite integral is $F(b) - F(a)$. The constant $C$ cancels out when subtracting, so you don't need it.","Worked example: $\\int_{1}^{3} 2x\\,dx$. An antiderivative is $x^{2}$, so the result is $3^{2} - 1^{2} = 8$.","Another one: $\\int_{0}^{2} (3x^{2} + 1)\\,dx$. With the antiderivative $x^{3} + x$, you get $(2^{3} + 2) - (0^{3} + 0) = 10$.","If the curve is below the axis, the integral comes out negative: $\\int_{0}^{1} (-4x^{3})\\,dx$ equals $-1$. For the geometric area you take the absolute value of each part.","Common mistakes: subtracting the wrong way ($F(a) - F(b)$ changes the sign); evaluating the function $f$ instead of the antiderivative; and forgetting that a definite integral is a number, not a function."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Compute $\\int_{0}^{3} 2x\\,dx$.","opciones":["6","3","18","9"],"respuesta":"9","explicacion":"Antiderivative $x^{2}$: $3^{2} - 0^{2} = 9$."},{"pregunta":"Compute $\\int_{1}^{2} 3x^{2}\\,dx$.","opciones":["7","8","9","3"],"respuesta":"7","explicacion":"Antiderivative $x^{3}$: $2^{3} - 1^{3} = 7$."},{"pregunta":"If $F$ is an antiderivative of $f$, what is $\\int_{a}^{b} f(x)\\,dx$?","opciones":["$F(a) - F(b)$","$f(b) - f(a)$","$F(b) + F(a)$","$F(b) - F(a)$"],"respuesta":"$F(b) - F(a)$","explicacion":"Fundamental theorem: the antiderivative at the upper limit minus at the lower one."},{"pregunta":"Why don't you write $+ C$ in a definite integral?","opciones":["Because it's always 0","Because it only goes in derivatives","Because it cancels out when subtracting","Because the area is positive"],"respuesta":"Because it cancels out when subtracting","explicacion":"$(F(b) + C) - (F(a) + C) = F(b) - F(a)$."},{"pregunta":"Compute $\\int_{0}^{1} (-4x^{3})\\,dx$.","opciones":["-1","1","-4","0"],"respuesta":"-1","explicacion":"Antiderivative $-x^{4}$: $-1 - 0 = -1$ (the curve is below the axis)."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"calculia.area","despuesDePaso":2,"titulo":"$\\int_1^3 2x\\,dx$: $3^2 - 1^2 = 8$","funcion":[{"tipo":"potencia","c":2,"n":1}],"desde":1,"hasta":3},{"tipo":"calculia.area","despuesDePaso":3,"titulo":"$\\int_0^2 (3x^2+1)\\,dx$: $(2^3 + 2) - 0 = 10$","funcion":[{"tipo":"potencia","c":3,"n":2},{"tipo":"potencia","c":1,"n":0}],"desde":0,"hasta":2}]$leccion_en$::jsonb
    )
where slug = 'calculia-clase-integral-definida';

update public.techniques
set nombre_en = 'Integrals of the exponential and of k over x',
    descripcion_en = 'Why $e^{x}$ is its own integral, how $e^{ax}$ is integrated by dividing by $a$, and why $\dfrac{k}{x}$ gives $k\ln|x|$.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["The exponential $e^{x}$ (with e approximately $2{,}718$) is the only function that is its own derivative: $(e^{x})' = e^{x}$. That's why $\\int e^{x}\\,dx = e^{x} + C$.","With a number times x in the exponent, the chain rule brings that number out when differentiating, and when integrating you have to divide by it. Examples: $\\int e^{2x}\\,dx = \\dfrac{e^{2x}}{2} + C$ and $\\int 12e^{3x}\\,dx = 4e^{3x} + C$.","The logarithm shows up with $\\dfrac{1}{x}$: since $(\\ln|x|)' = \\dfrac{1}{x}$, you get $\\int \\dfrac{1}{x}\\,dx = \\ln|x| + C$.","With a coefficient, the number comes out in front: $\\int \\dfrac{7}{x}\\,dx = 7\\ln|x| + C$.","It's exactly the exponent $-1$ case that the power rule doesn't cover. For any other exponent the rule still works, negative ones too: $\\int x^{-2}\\,dx = -x^{-1} + C$.","Common mistakes: multiplying by the number in the exponent instead of dividing when integrating $e^{ax}$; writing the logarithm without absolute value (it fails for negative x); and applying the power rule to $\\dfrac{1}{x}$."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Compute $\\int e^{5x}\\,dx$.","opciones":["$5e^{5x} + C$","$e^{5x} + C$","$\\dfrac{e^{5x}}{5} + C$","$\\dfrac{e^{6x}}{6} + C$"],"respuesta":"$\\dfrac{e^{5x}}{5} + C$","explicacion":"You divide by the 5 in the exponent."},{"pregunta":"Compute $\\int 8e^{2x}\\,dx$.","opciones":["$16e^{2x} + C$","$8e^{2x} + C$","$4e^{2x} + C$","$2e^{2x} + C$"],"respuesta":"$4e^{2x} + C$","explicacion":"$\\dfrac{8}{2}e^{2x} = 4e^{2x}$."},{"pregunta":"Compute $\\int \\dfrac{3}{x}\\,dx$.","opciones":["$-\\dfrac{3}{x^{2}} + C$","$3x + C$","$\\ln|3x| + C$","$3\\ln|x| + C$"],"respuesta":"$3\\ln|x| + C$","explicacion":"The 3 comes out in front: $3\\ln|x|$."},{"pregunta":"Compute $\\int x^{-3}\\,dx$.","opciones":["$-3x^{-4} + C$","$\\ln|x^{3}| + C$","$\\dfrac{1}{2}x^{-2} + C$","$-\\dfrac{1}{2}x^{-2} + C$"],"respuesta":"$-\\dfrac{1}{2}x^{-2} + C$","explicacion":"New exponent $-2$ and you divide by $-2$."},{"pregunta":"Why does the logarithm in the integral of $\\dfrac{1}{x}$ have an absolute value?","opciones":["So the formula also works with negative x","So the result is a whole number","Because that makes it easier to differentiate","Because the logarithm of 1 is 0"],"respuesta":"So the formula also works with negative x","explicacion":"The logarithm only exists for positive numbers; with the absolute value it works for every x other than 0."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":1,"titulo":"Exponential and logarithm","cuadros":[{"texto":"Differentiating multiplies by 3","formula":"(e^{3x})' = 3e^{3x}"},{"texto":"Integrating divides by 3","formula":"\\int e^{3x}\\,dx = \\dfrac{e^{3x}}{3} + C"},{"texto":"The k over x case","formula":"\\int \\dfrac{2}{x}\\,dx = 2\\ln|x| + C"}]}]$leccion_en$::jsonb
    )
where slug = 'calculia-clase-exponencial-y-logaritmo';

update public.techniques
set nombre_en = 'Integrals of sine and cosine',
    descripcion_en = 'The derivatives of sine and cosine in reverse, the minus sign people forget most, coefficients and the case of a number inside the cosine.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["The two basic derivatives: $(\\sin(x))' = \\cos(x)$ and $(\\cos(x))' = -\\sin(x)$. Everything else comes from there.","In reverse: $\\int \\cos(x)\\,dx = \\sin(x) + C$ and $\\int \\sin(x)\\,dx = -\\cos(x) + C$.","With a coefficient, the number comes out in front: $\\int 5\\cos(x)\\,dx = 5\\sin(x) + C$ and $\\int 7\\sin(x)\\,dx = -7\\cos(x) + C$.","With a number inside, you divide by it (it's the chain rule in reverse): $\\int \\cos(2x)\\,dx = \\dfrac{\\sin(2x)}{2} + C$.","To get the sign right, differentiate your result and compare it with what was inside the integral: $(-7\\cos(x))' = 7\\sin(x)$, correct.","Common mistakes: putting the minus on the sine instead of on the cosine; forgetting to divide by the number inside; and confusing integrating with differentiating (integrating cosine gives sine, differentiating cosine gives minus sine)."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Compute $\\int 3\\sin(x)\\,dx$.","opciones":["$3\\cos(x) + C$","$-3\\sin(x) + C$","$3\\sin(x) + C$","$-3\\cos(x) + C$"],"respuesta":"$-3\\cos(x) + C$","explicacion":"Integrating sine gives minus cosine."},{"pregunta":"Compute $\\int 4\\cos(x)\\,dx$.","opciones":["$-4\\sin(x) + C$","$4\\cos(x) + C$","$-4\\cos(x) + C$","$4\\sin(x) + C$"],"respuesta":"$4\\sin(x) + C$","explicacion":"Integrating cosine gives sine, with no minus sign."},{"pregunta":"Compute $\\int \\cos(3x)\\,dx$.","opciones":["$3\\sin(3x) + C$","$\\sin(3x) + C$","$\\dfrac{\\sin(3x)}{3} + C$","$-\\dfrac{\\sin(3x)}{3} + C$"],"respuesta":"$\\dfrac{\\sin(3x)}{3} + C$","explicacion":"You divide by the 3 inside."},{"pregunta":"What is the derivative of $\\sin(x)$?","opciones":["$-\\cos(x)$","$\\cos(x)$","$-\\sin(x)$","$\\sin(x)$"],"respuesta":"$\\cos(x)$","explicacion":"Differentiating sine gives cosine."},{"pregunta":"When integrating the sine, where does the minus sign go?","opciones":["In front of the sine","There's no minus sign","In the constant C","In front of the cosine of the result"],"respuesta":"In front of the cosine of the result","explicacion":"$\\int \\sin(x)\\,dx = -\\cos(x) + C$."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":2,"titulo":"Sine and cosine when integrating","cuadros":[{"texto":"Integrating cosine gives sine","formula":"\\int 3\\cos(x)\\,dx = 3\\operatorname{sen}(x) + C"},{"texto":"Integrating sine gives minus cosine","formula":"\\int 4\\operatorname{sen}(x)\\,dx = -4\\cos(x) + C"},{"texto":"Check by differentiating","formula":"(-4\\cos(x))' = 4\\operatorname{sen}(x)"}]}]$leccion_en$::jsonb
    )
where slug = 'calculia-clase-integrales-trigonometricas';

update public.techniques
set nombre_en = 'Integration by substitution: the u change of variable',
    descripcion_en = 'How to spot when it works, choose $u$, swap $dx$ for $du$, integrate and go back to x, with examples like the ones in Practice.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Substitution is the chain rule in reverse. It works when inside the integral there's a composite function and, multiplying, the derivative of the inside (or a multiple of it).","Step 1: choose $u$ equal to the inside. Step 2: differentiate to get $du$ and solve for $dx$. Step 3: rewrite the whole integral in $u$ (no x should be left). Step 4: integrate. Step 5: put the inside back in place of $u$.","Worked example: in $\\int 12(3x-1)^{3}\\,dx$, with $u = 3x-1$ you have $du = 3\\,dx$, so $dx = \\dfrac{du}{3}$. You're left with $\\int 4u^{3}\\,du$, which gives $u^{4} + C$, that is, $(3x-1)^{4} + C$.","Check with the chain rule: $((3x-1)^{4})' = 4(3x-1)^{3}\\cdot 3 = 12(3x-1)^{3}$. That's why $\\int 12(3x-1)^{3}\\,dx = (3x-1)^{4} + C$.","With the x multiplying outside: in $\\int 2x(x^{2}+1)^{5}\\,dx$, with $u = x^{2}+1$ the $du$ replaces exactly $2x\\,dx$. Result: $\\int 2x(x^{2}+1)^{5}\\,dx = \\dfrac{(x^{2}+1)^{6}}{6} + C$.","Common mistakes: forgetting to change $dx$ (and ending up with one factor too many or too few); leaving x and $u$ mixed; and not going back to x at the end. Always check by differentiating the result."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Compute $\\int 8(2x+1)^{3}\\,dx$.","opciones":["$2(2x+1)^{4} + C$","$4(2x+1)^{4} + C$","$(2x+1)^{4} + C$","$8(2x+1)^{3} + C$"],"respuesta":"$(2x+1)^{4} + C$","explicacion":"$u = 2x+1$, $du = 2\\,dx$: you get $\\int 4u^{3}\\,du = u^{4} + C$."},{"pregunta":"Compute $\\int 6x(x^{2}-4)^{2}\\,dx$.","opciones":["$3(x^{2}-4)^{3} + C$","$2x(x^{2}-4)^{3} + C$","$(x^{2}-4)^{2} + C$","$(x^{2}-4)^{3} + C$"],"respuesta":"$(x^{2}-4)^{3} + C$","explicacion":"$u = x^{2}-4$, $du = 2x\\,dx$: you get $\\int 3u^{2}\\,du = u^{3} + C$."},{"pregunta":"In $\\int 15(5x+2)^{2}\\,dx$, what's best to call $u$?","opciones":["$15$","$(5x+2)^{2}$","$5x+2$","$x$"],"respuesta":"$5x+2$","explicacion":"$u$ is the inside; its derivative (5) divides the 15."},{"pregunta":"If $u = 4x - 7$, what is $dx$ replaced by?","opciones":["$4\\,du$","$du$","$-7\\,du$","$\\dfrac{du}{4}$"],"respuesta":"$\\dfrac{du}{4}$","explicacion":"$du = 4\\,dx$, so $dx = \\dfrac{du}{4}$."},{"pregunta":"What's the last thing you have to do in a substitution?","opciones":["Write the result in x again","Differentiate $u$","Add 1 to the exponent","Multiply by $du$"],"respuesta":"Write the result in x again","explicacion":"The result has to be in the original variable."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":2,"titulo":"Substitution in $\\int 12(3x-1)^3\\,dx$","cuadros":[{"texto":"Choose $u$","formula":"u = 3x-1"},{"texto":"12 is 4 times the derivative of $u$","formula":"(3x-1)' = 3"},{"texto":"Integrate in $u$ and go back to x","formula":"\\int 12(3x-1)^3\\,dx = (3x-1)^4 + C"}]},{"tipo":"calculia.area","despuesDePaso":3,"titulo":"Area under $12(3x-1)^3$ between $0{,}5$ and 1","funcion":[{"tipo":"factorLineal","c":12,"a":3,"b":-1,"n":3}],"desde":0.5,"hasta":1}]$leccion_en$::jsonb
    )
where slug = 'calculia-clase-sustitucion';

update public.techniques
set nombre_en = 'Sequences, series and partial sums',
    descripcion_en = 'What a sequence is, what adding infinitely many terms means, how partial sums are used to decide whether a series converges, and why the terms must go to 0.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["A sequence is an infinite list of numbers with a rule: $a_{n} = \\dfrac{1}{n}$ gives $1, \\dfrac{1}{2}, \\dfrac{1}{3}, \\dots$ A series is the sum of all its terms: $\\sum_{n=1}^{\\infty} a_{n}$.","You can't add infinitely many numbers at once, so you look at the partial sums: $S_{1}$ is the first term, $S_{2}$ the sum of the first two, $S_{3}$ that of the first three, and so on. $S_{n}$ is the sum of the first n terms.","If the partial sums approach a number, the series converges and its sum is that number. If they grow without limit or don't settle down, it diverges.","Example: $1 + \\dfrac{1}{2} + \\dfrac{1}{4} + \\dfrac{1}{8} + \\dots$ has partial sums $1, \\dfrac{3}{2}, \\dfrac{7}{4}, \\dfrac{15}{8}$..., closer and closer to 2: it converges to 2.","Necessary condition: if a series converges, its terms go to 0. That's why $1 + 1 + 1 + \\dots$ and $1 - 1 + 1 - 1 + \\dots$ diverge. But it's not enough: the harmonic series $1 + \\dfrac{1}{2} + \\dfrac{1}{3} + \\dots$ has terms that go to 0 and still diverges.","Common mistakes: confusing the sequence (the terms) with the series (their sum); thinking that if the terms shrink the series always converges (the harmonic series shows it doesn't); and believing an infinite sum always gives infinity."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"What is $S_{3}$ for the series $2 + 4 + 6 + 8 + \\dots$?","opciones":["6","20","8","12"],"respuesta":"12","explicacion":"The sum of the first three terms: $2 + 4 + 6 = 12$."},{"pregunta":"What's the difference between a sequence and a series?","opciones":["They're the same","The series is the sum of the terms of the sequence","The sequence is infinite and the series isn't","The series only has positive numbers"],"respuesta":"The series is the sum of the terms of the sequence","explicacion":"The sequence is the list; the series, its sum."},{"pregunta":"If the terms of a series don't go to 0, the series...","opciones":["Converges","Can converge or diverge","Diverges"],"respuesta":"Diverges","explicacion":"Going to 0 is a necessary condition for converging."},{"pregunta":"The terms of the harmonic series go to 0. Does the series converge?","opciones":["Yes, it converges to 1","Yes, it converges to 2","No, it diverges"],"respuesta":"No, it diverges","explicacion":"Terms going to 0 isn't enough: the harmonic series diverges."},{"pregunta":"The partial sums of $1 + \\dfrac{1}{2} + \\dfrac{1}{4} + \\dots$ approach...","opciones":["1","2","$\\dfrac{3}{2}$","Infinity"],"respuesta":"2","explicacion":"It's a geometric series with ratio one half: $\\dfrac{1}{1-\\frac{1}{2}} = 2$."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"calculia.serie","despuesDePaso":3,"titulo":"Partial sums of $1 + \\frac{1}{2} + \\frac{1}{4} + \\dots$","a":1,"rNum":1,"rDen":2,"terminos":8}]$leccion_en$::jsonb
    )
where slug = 'calculia-clase-sucesiones-y-series';

update public.techniques
set nombre_en = 'The p-series and the harmonic series',
    descripcion_en = 'When $\sum \dfrac{1}{n^{p}}$ converges, why the harmonic series diverges even though its terms go to 0, and how to tell it apart from a geometric one.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["A p-series has the form $\\sum_{n=1}^{\\infty} \\dfrac{1}{n^{p}}$, with $p$ a fixed number. With $p = 2$ it's $1 + \\dfrac{1}{4} + \\dfrac{1}{9} + \\dots$; with $p = 1$ it's the harmonic series.","The rule: it converges if $p > 1$ and diverges if $p \\leq 1$. That's all you need to classify it.","Why the harmonic series diverges: group its terms. $\\dfrac{1}{3} + \\dfrac{1}{4} > \\dfrac{1}{2}$, and $\\dfrac{1}{5} + \\dfrac{1}{6} + \\dfrac{1}{7} + \\dfrac{1}{8} > \\dfrac{1}{2}$, and so on forever: you add infinitely many blocks bigger than one half, and the sum grows without limit.","With $p = 2$ the partial sums settle near $1{,}64$; with $p = 0{,}5$ they grow even faster than the harmonic series. A bigger $p$ shrinks the terms faster.","Don't confuse it with the geometric one: in $\\dfrac{1}{n^{2}}$ the $n$ is in the base and the exponent is fixed (p-series); in $\\left(\\dfrac{1}{2}\\right)^{n}$ the $n$ is in the exponent (geometric).","Common mistakes: saying $p = 1$ converges because the terms go to 0; applying the formula $\\dfrac{a}{1-r}$ to a p-series (it only works for geometric ones); and confusing $p > 1$ with $p \\geq 1$."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Does the series $\\sum \\dfrac{1}{n^{4}}$ converge or diverge?","opciones":["It diverges","It converges"],"respuesta":"It converges","explicacion":"A p-series with $p = 4 > 1$."},{"pregunta":"Does the series $\\sum \\dfrac{1}{n^{0{,}5}}$ converge or diverge?","opciones":["It diverges","It converges"],"respuesta":"It diverges","explicacion":"A p-series with $p = 0{,}5 \\leq 1$."},{"pregunta":"Why does the harmonic series diverge?","opciones":["Its terms group into infinitely many blocks bigger than one half","Because its terms don't go to 0","Because $p > 1$","Because it's geometric"],"respuesta":"Its terms group into infinitely many blocks bigger than one half","explicacion":"Each block adds up to more than one half, and there are infinitely many blocks."},{"pregunta":"Which of these is a p-series?","opciones":["$\\sum \\left(\\dfrac{1}{3}\\right)^{n}$","$\\sum 3^{n}$","$\\sum \\dfrac{1}{n^{3}}$","$\\sum \\dfrac{3}{2^{n}}$"],"respuesta":"$\\sum \\dfrac{1}{n^{3}}$","explicacion":"In the p-series the $n$ is in the base with a fixed exponent."},{"pregunta":"For which values of $p$ does the p-series diverge?","opciones":["$p > 1$","$p \\leq 1$","$p < 0$","Only $p = 1$"],"respuesta":"$p \\leq 1$","explicacion":"It diverges exactly when $p \\leq 1$."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":2,"titulo":"Converges or diverges depending on p","cuadros":[{"texto":"$p = 2$","formula":"1 + \\dfrac{1}{4} + \\dfrac{1}{9} + \\dfrac{1}{16} + \\dots","resaltar":"Con 10 términos suma $1{,}55$: converge"},{"texto":"$p = 1$, the harmonic series","formula":"1 + \\dfrac{1}{2} + \\dfrac{1}{3} + \\dfrac{1}{4} + \\dots","resaltar":"Con 1000 términos ya pasa de 7: diverge"},{"texto":"Grouping the harmonic series","formula":"\\dfrac{1}{3} + \\dfrac{1}{4} > \\dfrac{1}{2}"}]}]$leccion_en$::jsonb
    )
where slug = 'calculia-clase-serie-p';

update public.techniques
set nombre_en = 'The ratio test',
    descripcion_en = 'How to compare each term with the next one to decide whether a series converges, what to do when the limit is 1 and how it applies to $a_{n} = c\cdot r^{n}$, the case in Practice.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Idea: if from some point on each term is a fixed fraction of the previous one, less than 1, the terms shrink like in a convergent geometric series. The ratio test measures that fraction.","You compute $L = \\lim_{n\\to\\infty}\\left|\\dfrac{a_{n+1}}{a_{n}}\\right|$. If $L < 1$, it converges; if $L > 1$, it diverges; if L is 1, the test doesn't decide.","In Practice the sequences are $a_{n} = c\\cdot r^{n}$. When you divide a term by the previous one, the $c$ cancels out and $r$ is left, so L is the absolute value of $r$.","Worked example: for $a_{n} = 7\\cdot\\left(-\\dfrac{3}{4}\\right)^{n}$ the quotient is minus three quarters and its absolute value is $0{,}75$, less than 1: it converges.","With another form: for $a_{n} = \\dfrac{2^{n}}{n}$, the quotient is $\\dfrac{2n}{n+1}$, which goes to 2. Since L is 2, greater than 1, it diverges.","Common mistakes: forgetting the absolute value (with a negative ratio, L is positive); flipping the quotient ($\\dfrac{a_{n}}{a_{n+1}}$ gives the reciprocal and changes the conclusion); and concluding something when L is 1: the harmonic series and the p-series with $p = 2$ both give 1, and one diverges while the other converges."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"For $a_{n} = 6\\cdot\\left(\\dfrac{2}{5}\\right)^{n}$, what is L?","opciones":["6","2.4","2.5","0.4"],"respuesta":"0.4","explicacion":"The $c = 6$ cancels out and L is $\\dfrac{2}{5} = 0{,}4$."},{"pregunta":"For $a_{n} = 3\\cdot\\left(-\\dfrac{5}{4}\\right)^{n}$, what does the ratio test say?","opciones":["It converges","It diverges","The test doesn't decide"],"respuesta":"It diverges","explicacion":"L is $\\dfrac{5}{4}$, greater than 1."},{"pregunta":"If L is 1, what does the ratio test conclude?","opciones":["That it converges","Nothing: you have to use another test","That it diverges"],"respuesta":"Nothing: you have to use another test","explicacion":"With L equal to 1 some series converge and others diverge."},{"pregunta":"In $a_{n} = c\\cdot r^{n}$, why doesn't the value of $c$ matter for L?","opciones":["Because it's always 1","Because it's negative","Because it's in the exponent","Because it cancels out when dividing"],"respuesta":"Because it cancels out when dividing","explicacion":"$\\dfrac{c\\cdot r^{n+1}}{c\\cdot r^{n}} = r$."},{"pregunta":"For $a_{n} = 2\\cdot\\left(-\\dfrac{1}{3}\\right)^{n}$, what is L?","opciones":["$-\\dfrac{1}{3}$","$\\dfrac{1}{3}$","$\\dfrac{2}{3}$","3"],"respuesta":"$\\dfrac{1}{3}$","explicacion":"The absolute value of the ratio: $\\dfrac{1}{3}$."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"calculia.serie","despuesDePaso":2,"titulo":"$a_n = 4\\cdot\\left(\\frac{1}{2}\\right)^n$: L is $\\frac{1}{2}$ and it converges","a":2,"rNum":1,"rDen":2,"terminos":8}]$leccion_en$::jsonb
    )
where slug = 'calculia-clase-criterio-de-la-razon';

update public.techniques
set nombre_en = 'Partial derivatives of polynomials in x and y',
    descripcion_en = 'How to differentiate a polynomial with several mixed terms with respect to one variable, what happens to the terms without that variable and how to read the result.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["A function of two variables, like $f(x,y) = 3x^{2}y + 5xy^{3} - 2y^{2}$, gives a value for each pair (x, y). Its partial derivative with respect to x measures how $f$ changes if you only move x.","For $\\dfrac{\\partial f}{\\partial x}$, y is a fixed number: differentiate each term with the power rule in x and leave the powers of y multiplying, unchanged.","Term by term: $3x^{2}y$ gives $6xy$; $5xy^{3}$ gives $5y^{3}$; $-2y^{2}$ has no x and gives 0. Result: the partial with respect to x is $6xy + 5y^{3}$.","With respect to y, the other way around: $3x^{2}y$ gives $3x^{2}$; $5xy^{3}$ gives $15xy^{2}$; $-2y^{2}$ gives $-4y$. Result: the partial with respect to y is $3x^{2} + 15xy^{2} - 4y$.","Interpretation: at the point (1, 2), the partial with respect to x is $6\\cdot 1\\cdot 2 + 5\\cdot 2^{3} = 52$. If you move x a tiny bit with y fixed at 2, $f$ changes about 52 times what you moved.","Common mistakes: also differentiating the other variable (multiplying by both exponents); making the other variable disappear instead of leaving it multiplying; and forgetting that a term without the variable of the partial gives 0."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"For $f(x,y) = 2x^{3}y^{2} + 4y$, compute $\\dfrac{\\partial f}{\\partial x}$.","opciones":["$6x^{2}y^{2} + 4$","$12x^{2}y$","$6x^{2}$","$6x^{2}y^{2}$"],"respuesta":"$6x^{2}y^{2}$","explicacion":"$2x^{3}y^{2}$ gives $6x^{2}y^{2}$ and $4y$ has no x."},{"pregunta":"For $f(x,y) = 2x^{3}y^{2} + 4y$, compute $\\dfrac{\\partial f}{\\partial y}$.","opciones":["$4x^{3}y$","$6x^{2}y^{2} + 4$","$12x^{2}y + 4$","$4x^{3}y + 4$"],"respuesta":"$4x^{3}y + 4$","explicacion":"$2x^{3}y^{2}$ gives $4x^{3}y$ and $4y$ gives 4."},{"pregunta":"For $f(x,y) = x^{2} + xy + y^{2}$, compute $\\dfrac{\\partial f}{\\partial x}$.","opciones":["$2x + 2y$","$2x$","$2x + y$","$x + 2y$"],"respuesta":"$2x + y$","explicacion":"$x^{2}$ gives $2x$, $xy$ gives $y$ and $y^{2}$ gives 0."},{"pregunta":"When computing $\\dfrac{\\partial f}{\\partial x}$, what happens to $y^{3}$ inside $5xy^{3}$?","opciones":["It disappears","It stays multiplying, unchanged","It's differentiated into $3y^{2}$","It becomes 1"],"respuesta":"It stays multiplying, unchanged","explicacion":"For the partial in x, $y^{3}$ is a fixed number."},{"pregunta":"For $f(x,y) = 3x^{2}y + 5xy^{3} - 2y^{2}$, what is $\\dfrac{\\partial f}{\\partial x}$ at (1, 2)?","opciones":["12","40","52","56"],"respuesta":"52","explicacion":"$6\\cdot 1\\cdot 2 + 5\\cdot 2^{3} = 12 + 40 = 52$."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":2,"titulo":"With respect to x in $3x^2y + 5xy^3 - 2y^2$","cuadros":[{"texto":"$3x^2y$","formula":"6xy"},{"texto":"$5xy^3$: the $y^3$ stays","formula":"5y^3"},{"texto":"$-2y^2$ has no x","formula":"0","resaltar":"Total: $6xy + 5y^3$"}]}]$leccion_en$::jsonb
    )
where slug = 'calculia-clase-parciales-polinomios';

update public.techniques
set nombre_en = 'What is a differential equation?',
    descripcion_en = 'An equation whose unknown is a function: what solving it means, why the general solution has a constant and how to check a solution.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["In an ordinary equation the unknown is a number. In a differential equation (ODE) the unknown is a function $y(x)$, and the equation relates $y$ to its derivative. For example: $\\dfrac{dy}{dx} = 2x$.","Solving it means finding all the functions that satisfy it. For $\\dfrac{dy}{dx} = 2x$ it's enough to integrate: $y = x^{2} + C$. There are infinitely many solutions, one for each value of $C$: that family is the general solution.","To check a solution, differentiate and substitute. With $x^{2} + 3$: $(x^{2} + 3)' = 2x$, which is what the equation asks for.","Many ODEs mix $y$ with its derivative, like $\\dfrac{dy}{dx} = 3y$: the derivative depends on the function itself. Its general solution is $y = A\\cdot e^{3x}$. Check with A equal to 1: $(e^{3x})' = 3e^{3x}$.","An initial condition picks a single curve out of the family: if also y is 5 when x is 0, then A is 5 (because $e^{0} = 1$) and the solution is $y = 5e^{3x}$.","Common mistakes: forgetting the constant (without it the whole family of solutions is missing); confusing the ODE with its solution; and not checking: differentiating the proposed solution and substituting always tells you whether it's right."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"What is the unknown in a differential equation?","opciones":["A number","A derivative at a point","A function","A constant"],"respuesta":"A function","explicacion":"You're looking for a function $y(x)$ that satisfies the equation."},{"pregunta":"What is the general solution of $\\dfrac{dy}{dx} = 6x^{2}$?","opciones":["$y = 12x + C$","$y = 6x^{3} + C$","$y = 2x^{3} + C$","$y = 2x^{3}$"],"respuesta":"$y = 2x^{3} + C$","explicacion":"Integrating $6x^{2}$ gives $2x^{3}$, and the general solution has the constant."},{"pregunta":"Is $y = 4e^{2x}$ a solution of $\\dfrac{dy}{dx} = 2y$?","opciones":["No","Yes"],"respuesta":"Yes","explicacion":"Its derivative is $8e^{2x}$, which is 2 times $4e^{2x}$."},{"pregunta":"What is an initial condition for?","opciones":["To differentiate the equation","To pick a single solution out of the family","To get rid of the derivative","To know whether the ODE is separable"],"respuesta":"To pick a single solution out of the family","explicacion":"It fixes the value of the constant."},{"pregunta":"Why does the general solution have a constant?","opciones":["Because an arbitrary constant appears when integrating","Because every function has one","Because the derivative of the constant is 1","Because that's how the initial condition is written"],"respuesta":"Because an arbitrary constant appears when integrating","explicacion":"Two solutions that differ by that constant have the same derivative."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"calculia.edo","despuesDePaso":3,"titulo":"Family of solutions of $\\dfrac{dy}{dx} = 3y$","k":3,"n":0,"x0":0.3,"rango":[-1,0.8]}]$leccion_en$::jsonb
    )
where slug = 'calculia-clase-que-es-una-edo';

update public.techniques
set nombre_en = 'Exponential growth and decay',
    descripcion_en = 'The most used ODE model, the derivative proportional to the function: how to solve it by separating variables, what its constants mean and where it shows up (populations, money, isotopes).',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["The equation $\\dfrac{dy}{dx} = k\\cdot y$ says the quantity changes in proportion to what's there. It's the $n = 0$ case of the separable ODEs $\\dfrac{dy}{dx} = k\\cdot x^{n}\\cdot y$ in Practice.","Separating variables: $\\dfrac{dy}{y} = k\\,dx$. Integrating both sides, the logarithm of y is $kx$ plus a constant; solving, $y = A\\cdot e^{kx}$.","Interpretation: $A$ is the initial value (when x is 0) and $k$ the rate. With $k > 0$ it's growth (a population, money with compound interest); with $k < 0$ it's decay (a radioactive isotope, a medicine being eliminated).","Example: a colony of 200 bacteria grows with $k = 0{,}5$ per hour. Then $y = 200e^{0{,}5x}$ and, after 2 hours, there are $200e$, about 544 bacteria.","Doubling time: with $k > 0$ the quantity doubles every $\\dfrac{\\ln 2}{k}$ units of time. With $k = 0{,}5$, about every $1{,}39$ hours.","Common mistakes: writing $e^{kx} + A$ (the constant multiplies, it doesn't add); confusing the sign of $k$ with that of $A$; and forgetting that $A$ is the value when x is 0."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"What is the general solution of $\\dfrac{dy}{dx} = -2y$?","opciones":["$y = A\\cdot e^{2x}$","$y = -2x + A$","$y = A\\cdot e^{-2x}$","$y = e^{-2x} + A$"],"respuesta":"$y = A\\cdot e^{-2x}$","explicacion":"The derivative is $-2$ times the function: $A\\cdot e^{-2x}$."},{"pregunta":"In $y = A\\cdot e^{kx}$ with $k < 0$, the quantity...","opciones":["Grows over time","Stays the same","Decreases over time","Oscillates"],"respuesta":"Decreases over time","explicacion":"With a negative $k$, the exponential shrinks."},{"pregunta":"If $y = 300e^{0{,}1x}$, what is y when x is 0?","opciones":["0","30","300","1"],"respuesta":"300","explicacion":"$e^{0} = 1$, so y is 300."},{"pregunta":"Which case of $\\dfrac{dy}{dx} = k\\cdot x^{n}\\cdot y$ is exponential growth?","opciones":["$n = 1$","$k = 0$","$n = 0$","$n = -1$"],"respuesta":"$n = 0$","explicacion":"With $n = 0$, $x^{0} = 1$ and you're left with $\\dfrac{dy}{dx} = k\\cdot y$."},{"pregunta":"With $k = 0{,}5$, about how often does the quantity double?","opciones":["2","0.5","0.69","1.39"],"respuesta":"1.39","explicacion":"$\\dfrac{\\ln 2}{0{,}5} \\approx 1{,}39$."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"calculia.edo","despuesDePaso":2,"titulo":"Growth: $\\dfrac{dy}{dx} = y$","k":1,"n":0,"x0":0.5,"rango":[-1.2,1.2]},{"tipo":"calculia.edo","despuesDePaso":2,"titulo":"Decay: $\\dfrac{dy}{dx} = -y$","k":-1,"n":0,"x0":0.5,"rango":[-1.2,1.2]}]$leccion_en$::jsonb
    )
where slug = 'calculia-clase-crecimiento-exponencial';
